// end of generated

type InputElement = HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement;

export type InputProps<T extends InputElement = HTMLInputElement> = CommonAttributes &
	WebAttributes<T> &
	Pick<
		AriaAttributes,
		| 'aria-label'
		| 'aria-labelledby'
		| 'aria-describedby'
		| 'aria-invalid'
		| 'aria-required'
		| 'aria-disabled'
		| 'aria-controls'
		| 'aria-expanded'
		| 'aria-haspopup'
		| 'aria-activedescendant'
		| 'aria-autocomplete'
		| 'aria-keyshortcuts'
		| 'aria-hidden'
	> &
	// What forms (react-hook-form's `register` and `field` included) and comboboxes hand an input
	Pick<
		InputHTMLAttributes<T>,
		| 'name'
		| 'value'
		| 'defaultValue'
		| 'disabled'
		| 'readOnly'
		| 'required'
		| 'autoFocus'
		| 'autoComplete'
		| 'autoCapitalize'
		| 'autoCorrect'
		| 'inputMode'
		| 'spellCheck'
		| 'placeholder'
		| 'min'
		| 'max'
		| 'step'
		| 'minLength'
		| 'maxLength'
		| 'pattern'
		| 'multiple'
		| 'accept'
		| 'type'
		| 'hidden'
		| 'onChange'
	> &
	Pick<TextareaHTMLAttributes<HTMLTextAreaElement>, 'rows' | 'cols'> &
	Pick<
		DOMAttributes<T>,
		| 'onInput'
		| 'onBlur'
		| 'onFocus'
		| 'onClick'
		| 'onMouseDown'
		| 'onKeyDown'
		| 'onKeyUp'
		| 'onPaste'
		| 'onDrop'
		| 'onDragOver'
		| 'onDragEnter'
		| 'onDragLeave'
	> & {
		/** The element to render: a text-like `input`, a `textarea` or a `select`. */
		is?: 'input' | 'textarea' | 'select';
		/** The `size` attribute of the element. */
		htmlSize?: number;
		/** Hides the input and keeps its space. */
		invisible?: boolean;
		role?: AriaRole;
		tabIndex?: number;
		/** The `option`s of a `select`. */
		children?: ReactNode;
	};

// The modifiers `InputBox` passes as `rcx-*` attributes, outside the public props
type InputBoxModifiers = {
	'rcx-input-box--type'?: string;
	'rcx-input-box--multiple'?: boolean;
	'rcx-input-box--placeholder-visible'?: boolean;
	'rcx-input-box--small'?: boolean;
	'rcx-input-box--undecorated'?: boolean;
};

// Set by `InputBoxWrapper`, which sizes the input it holds
export const InputBoxWrapperContext = createContext(false);

const UNDECORATED = 'rcx-input-box--undecorated';

function Input<T extends InputElement = HTMLInputElement>(props: InputProps<T> & InputBoxModifiers) {
	const {
		'is': tag = 'input',
		className,
		children,
		'rcx-input-box--type': type,
		'rcx-input-box--multiple': multiple,
		'rcx-input-box--placeholder-visible': placeholderVisible,
		'rcx-input-box--small': small,
		'rcx-input-box--undecorated': undecoratedProp,
	} = props;

	// Select and AutoComplete ask for it by class name
	const undecorated = Boolean(undecoratedProp) || (typeof className === 'string' && className.split(/\s+/).includes(UNDECORATED));
	const wrapped = useContext(InputBoxWrapperContext);

	const look = (undecorated && `${wrapped ? 'wrapped' : 'plain'}${small ? '-small' : ''}`) || (small && 'small') || 'decorated';
	const kind = (type === 'textarea' && 'textarea') || (type === 'select' && (multiple ? 'multiple' : 'select')) || 'text';

	const classes = [
		'rcx-box rcx-box--full rcx-box--animated rcx-input-box',
		type && `rcx-input-box--type-${type}`,
		multiple && 'rcx-input-box--multiple',
		placeholderVisible && 'rcx-input-box--placeholder-visible',
		small && 'rcx-input-box--small',
		undecoratedProp && UNDECORATED,
		className,
	]
		.filter(Boolean)
		.join(' ');

	// One branch per tag, each with a literal `render` element: zero-runtime has to know the tag
	if (tag === 'textarea') {
		return (
			<InputFrame
				look={look}
				kind={kind}
				placeholderVisible={Boolean(placeholderVisible)}
				invisible={Boolean(props.invisible)}
				className={classes}
				render={
					<textarea
						{...ariaAndDataAttributes(props)}
						name={props.name}
						value={props.value}
						defaultValue={props.defaultValue}
						disabled={props.disabled}
						readOnly={props.readOnly}
						required={props.required}
						// oxlint-disable-next-line jsx-a11y/no-autofocus -- the consumer's to set
						autoFocus={props.autoFocus}
						autoComplete={props.autoComplete}
						autoCapitalize={props.autoCapitalize}
						autoCorrect={props.autoCorrect}
						inputMode={props.inputMode}
						spellCheck={props.spellCheck}
						placeholder={props.placeholder}
						minLength={props.minLength}
						maxLength={props.maxLength}
						rows={props.rows}
						cols={props.cols}
						hidden={props.hidden}
						// The ref and handlers are typed for every tag, each branch renders one
						ref={props.ref as Ref<HTMLTextAreaElement>}
						id={props.id}
						title={props.title}
						role={props.role}
						tabIndex={props.tabIndex}
						onChange={props.onChange as DOMAttributes<HTMLTextAreaElement>['onChange']}
						onInput={props.onInput as DOMAttributes<HTMLTextAreaElement>['onInput']}
						onBlur={props.onBlur as DOMAttributes<HTMLTextAreaElement>['onBlur']}
						onFocus={props.onFocus as DOMAttributes<HTMLTextAreaElement>['onFocus']}
						onClick={props.onClick as DOMAttributes<HTMLTextAreaElement>['onClick']}
						onMouseDown={props.onMouseDown as DOMAttributes<HTMLTextAreaElement>['onMouseDown']}
						onKeyDown={props.onKeyDown as DOMAttributes<HTMLTextAreaElement>['onKeyDown']}
						onKeyUp={props.onKeyUp as DOMAttributes<HTMLTextAreaElement>['onKeyUp']}
						onPaste={props.onPaste as DOMAttributes<HTMLTextAreaElement>['onPaste']}
						onDrop={props.onDrop as DOMAttributes<HTMLTextAreaElement>['onDrop']}
						onDragOver={props.onDragOver as DOMAttributes<HTMLTextAreaElement>['onDragOver']}
						onDragEnter={props.onDragEnter as DOMAttributes<HTMLTextAreaElement>['onDragEnter']}
						onDragLeave={props.onDragLeave as DOMAttributes<HTMLTextAreaElement>['onDragLeave']}
					/>
				}
			/>
		);
	}

	if (tag === 'select') {
		return (
			<InputFrame
				look={look}
				kind={kind}
				placeholderVisible={Boolean(placeholderVisible)}
				invisible={Boolean(props.invisible)}
				className={classes}
				render={
					<select
						{...ariaAndDataAttributes(props)}
						name={props.name}
						value={props.value}
						defaultValue={props.defaultValue}
						disabled={props.disabled}
						required={props.required}
						// oxlint-disable-next-line jsx-a11y/no-autofocus -- the consumer's to set
						autoFocus={props.autoFocus}
						autoComplete={props.autoComplete}
						multiple={props.multiple}
						size={props.htmlSize}
						hidden={props.hidden}
						ref={props.ref as Ref<HTMLSelectElement>}
						id={props.id}
						title={props.title}
						role={props.role}
						tabIndex={props.tabIndex}
						onChange={props.onChange as DOMAttributes<HTMLSelectElement>['onChange']}
						onInput={props.onInput as DOMAttributes<HTMLSelectElement>['onInput']}
						onBlur={props.onBlur as DOMAttributes<HTMLSelectElement>['onBlur']}
						onFocus={props.onFocus as DOMAttributes<HTMLSelectElement>['onFocus']}
						onClick={props.onClick as DOMAttributes<HTMLSelectElement>['onClick']}
						onMouseDown={props.onMouseDown as DOMAttributes<HTMLSelectElement>['onMouseDown']}
						onKeyDown={props.onKeyDown as DOMAttributes<HTMLSelectElement>['onKeyDown']}
						onKeyUp={props.onKeyUp as DOMAttributes<HTMLSelectElement>['onKeyUp']}
					/>
				}
			>
				{children}
			</InputFrame>
		);
	}

	return (
		<InputFrame
			look={look}
			kind={kind}
			placeholderVisible={Boolean(placeholderVisible)}
			invisible={Boolean(props.invisible)}
			className={classes}
			render={
				<input
					{...ariaAndDataAttributes(props)}
					type={props.type}
					name={props.name}
					value={props.value}
					defaultValue={props.defaultValue}
					disabled={props.disabled}
					readOnly={props.readOnly}
					required={props.required}
					// oxlint-disable-next-line jsx-a11y/no-autofocus -- the consumer's to set
					autoFocus={props.autoFocus}
					autoComplete={props.autoComplete}
					autoCapitalize={props.autoCapitalize}
					autoCorrect={props.autoCorrect}
					inputMode={props.inputMode}
					spellCheck={props.spellCheck}
					placeholder={props.placeholder}
					min={props.min}
					max={props.max}
					step={props.step}
					minLength={props.minLength}
					maxLength={props.maxLength}
					pattern={props.pattern}
					multiple={props.multiple}
					accept={props.accept}
					size={props.htmlSize}
					hidden={props.hidden}
					ref={props.ref as Ref<HTMLInputElement>}
					id={props.id}
					title={props.title}
					role={props.role}
					tabIndex={props.tabIndex}
					onChange={props.onChange as DOMAttributes<HTMLInputElement>['onChange']}
					onInput={props.onInput as DOMAttributes<HTMLInputElement>['onInput']}
					onBlur={props.onBlur as DOMAttributes<HTMLInputElement>['onBlur']}
					onFocus={props.onFocus as DOMAttributes<HTMLInputElement>['onFocus']}
					onClick={props.onClick as DOMAttributes<HTMLInputElement>['onClick']}
					onMouseDown={props.onMouseDown as DOMAttributes<HTMLInputElement>['onMouseDown']}
					onKeyDown={props.onKeyDown as DOMAttributes<HTMLInputElement>['onKeyDown']}
					onKeyUp={props.onKeyUp as DOMAttributes<HTMLInputElement>['onKeyUp']}
					onPaste={props.onPaste as DOMAttributes<HTMLInputElement>['onPaste']}
					onDrop={props.onDrop as DOMAttributes<HTMLInputElement>['onDrop']}
					onDragOver={props.onDragOver as DOMAttributes<HTMLInputElement>['onDragOver']}
					onDragEnter={props.onDragEnter as DOMAttributes<HTMLInputElement>['onDragEnter']}
					onDragLeave={props.onDragLeave as DOMAttributes<HTMLInputElement>['onDragLeave']}
				/>
			}
		/>
	);
}

export default Input;
